var NOTE_NAMES=["C","C#","D","D#","E","F","F#","G","G#","A","A#","B"];
function midiToFreq(m){ return 440*Math.pow(2,(m-69)/12); }
function freqToMidi(f){ return 69+12*Math.log(f/440)/Math.log(2); }
function noteToMidi(note){
  note=String(note).trim();
  var m=note.match(/^([A-Ga-g])([#b]?)(-?\d+)$/);
  if(!m) return null;
  var idx=NOTE_NAMES.indexOf(m[1].toUpperCase());
  if(idx<0) return null;
  var acc=m[2]==='#'?1:(m[2]==='b'?-1:0);
  var oct=parseInt(m[3],10);
  return (oct+1)*12 + idx + acc;
}
function midiToNote(m){ m=Math.round(m); var idx=((m%12)+12)%12; var oct=Math.floor(m/12)-1; return NOTE_NAMES[idx]+oct; }
function noteToFreq(note){ var mm=noteToMidi(note); return mm==null?null:midiToFreq(mm); }
function freqToNote(f){ var mm=freqToMidi(f); return isFinite(mm)?midiToNote(mm):null; }
var EXPORTS={ NOTE_NAMES:NOTE_NAMES, midiToFreq:midiToFreq, freqToMidi:freqToMidi, noteToMidi:noteToMidi, midiToNote:midiToNote, noteToFreq:noteToFreq, freqToNote:freqToNote };

